CREATE TABLE IF NOT EXISTS "oa_leave" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "type" tinyint NOT NULL,
    "reason" varchar(500) NOT NULL,
    "start_time" timestamp NOT NULL,
    "end_time" timestamp NOT NULL,
    "day" decimal(5, 1) NOT NULL,
    "status" tinyint NOT NULL DEFAULT -1,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "start_user_select_assignees" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_business_trip" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "destination" varchar(200) NOT NULL,
    "reason" varchar(500) NOT NULL,
    "companion" varchar(200) DEFAULT NULL,
    "start_time" timestamp NOT NULL,
    "end_time" timestamp NOT NULL,
    "day" decimal(5, 1) NOT NULL,
    "vehicle" varchar(100) DEFAULT NULL,
    "estimated_amount" decimal(12, 2) DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT -1,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "start_user_select_assignees" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_loan" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "amount" decimal(12, 2) NOT NULL,
    "purpose" varchar(500) NOT NULL,
    "repayment_plan" varchar(500) DEFAULT NULL,
    "expected_repayment_time" timestamp DEFAULT NULL,
    "actual_repayment_time" timestamp DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT -1,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "start_user_select_assignees" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_visit" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "crm_customer_id" bigint DEFAULT NULL,
    "customer_name" varchar(100) NOT NULL,
    "contact_person" varchar(50) DEFAULT NULL,
    "contact_phone" varchar(20) DEFAULT NULL,
    "visit_address" varchar(200) DEFAULT NULL,
    "visit_time" timestamp NOT NULL,
    "purpose" varchar(500) NOT NULL,
    "result" text DEFAULT NULL,
    "next_visit_time" timestamp DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT -1,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "start_user_select_assignees" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_work_report" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "type" tinyint NOT NULL,
    "title" varchar(200) NOT NULL,
    "content" text NOT NULL,
    "plan" text DEFAULT NULL,
    "summary" text DEFAULT NULL,
    "report_date" date NOT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "reviewer_user_id" bigint DEFAULT NULL,
    "review_time" timestamp DEFAULT NULL,
    "review_content" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_schedule" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "title" varchar(200) NOT NULL,
    "description" varchar(500) DEFAULT NULL,
    "start_time" timestamp NOT NULL,
    "end_time" timestamp NOT NULL,
    "is_all_day" bit NOT NULL DEFAULT FALSE,
    "location" varchar(200) DEFAULT NULL,
    "type" tinyint NOT NULL DEFAULT 1,
    "priority" tinyint NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 0,
    "reminder_time" int DEFAULT NULL,
    "color" varchar(20) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_request" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "title" varchar(200) NOT NULL,
    "content" text NOT NULL,
    "type" tinyint NOT NULL DEFAULT 1,
    "urgency" tinyint NOT NULL DEFAULT 0,
    "attachment" varchar(2000) DEFAULT NULL,
    "expected_amount" decimal(12, 2) DEFAULT NULL,
    "status" tinyint NOT NULL DEFAULT -1,
    "process_instance_id" varchar(64) DEFAULT NULL,
    "start_user_select_assignees" varchar(2000) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_document_dir" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "parent_id" bigint NOT NULL DEFAULT 0,
    "name" varchar(100) NOT NULL,
    "type" tinyint NOT NULL DEFAULT 1,
    "sort" int NOT NULL DEFAULT 0,
    "description" varchar(500) DEFAULT NULL,
    "keywords" varchar(500) DEFAULT NULL,
    "owner_user_id" bigint DEFAULT NULL,
    "permission" tinyint NOT NULL DEFAULT 0,
    "file_url" varchar(500) DEFAULT NULL,
    "file_name" varchar(200) DEFAULT NULL,
    "file_type" varchar(50) DEFAULT NULL,
    "file_size" bigint DEFAULT NULL,
    "version" int DEFAULT 1,
    "status" tinyint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_task" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "project_id" bigint DEFAULT NULL,
    "title" varchar(200) NOT NULL,
    "description" varchar(500) DEFAULT NULL,
    "priority" tinyint DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 0,
    "assignee_user_id" bigint DEFAULT NULL,
    "start_time" timestamp DEFAULT NULL,
    "deadline" timestamp DEFAULT NULL,
    "completed_time" timestamp DEFAULT NULL,
    "progress" int DEFAULT 0,
    "tags" varchar(500) DEFAULT NULL,
    "attachment" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "oa_message" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "sender_user_id" bigint NOT NULL,
    "receiver_user_id" bigint NOT NULL,
    "title" varchar(200) NOT NULL,
    "content" text DEFAULT NULL,
    "read_status" tinyint NOT NULL DEFAULT 0,
    "read_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
